import java.util.*;
import java.io.*;
import java.math.*;

class Solution {

    public static void main(String args[]) {
        Scanner in = new Scanner(System.in);
        int N = in.nextInt();
        StringBuilder s = new StringBuilder();
        char p = 0;

        for (int i = 0; i < N; i++) {
            int[] b = new int[14];

            for (int j = 0; j < 14; j++) {
                b[j] = Integer.parseInt(in.next(), 16);
            }

            int[] v = new int[6];

            for (int j = 0; j < 6; j++) {
                int u = b[2 + j * 2] | (b[3 + j * 2] << 8);
                v[j] = u < 32768 ? u : u - 65536;
            }

            int k = 0;

            for (int j = 1; j < 3; j++) {
                if (Math.abs(v[j]) > Math.abs(v[k])) {
                    k = j;
                }
            }

            int a = Math.abs(v[3]) + Math.abs(v[4]) + Math.abs(v[5]);

            if (Math.abs(v[k]) < 400 || a < 3000) {
                continue;
            }

            char c = v[k] > 0 ? "RUF".charAt(k) : "LDB".charAt(k);

            if (c != p) {
                s.append(c);
                p = c;
            }
        }

        System.out.println(s.length() == 0 ? "LOCKED" : s.toString());
    }
}
